-- ── story 9-3b: the async audit export ─────────────────────────────────────
-- Generated by drizzle-kit (the two tables, the notifications column, the
-- indexes) and hand-amended below the marker: the CHECKs, the widened
-- notifications source CHECK, RLS and the post-migration probe (drizzle-kit
-- is blind to all four; `bun run db:generate` afterwards reports "No schema
-- changes").
--
-- Additive only: two new tables (written only by the tenancy module) and one
-- NULLABLE column on `notifications` (the notifications module's first
-- per-user audience). No data statement — no pre-flight, no fail-fast. No
-- foreign keys (IMPLEMENTATION-GUIDE §3): expiry removes an export's file
-- explicitly.
CREATE TABLE "audit_export_files" (
	"export_id" uuid PRIMARY KEY NOT NULL,
	"tenant_id" uuid NOT NULL,
	"content" "bytea" NOT NULL
);
--> statement-breakpoint
CREATE TABLE "audit_exports" (
	"id" uuid PRIMARY KEY NOT NULL,
	"tenant_id" uuid NOT NULL,
	"requested_by" uuid NOT NULL,
	"filters" jsonb NOT NULL,
	"snapshot_at" timestamp with time zone NOT NULL,
	"status" text NOT NULL,
	"attempts" integer DEFAULT 0 NOT NULL,
	"started_at" timestamp with time zone,
	"heartbeat_at" timestamp with time zone,
	"finished_at" timestamp with time zone,
	"expires_at" timestamp with time zone,
	"row_count" integer,
	"byte_size" integer,
	"sha256" text,
	"failure_reason" text,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL
);
--> statement-breakpoint
ALTER TABLE "notifications" ADD COLUMN "recipient_user_id" uuid;--> statement-breakpoint
CREATE INDEX "audit_exports_tenant_requester_created_idx" ON "audit_exports" USING btree ("tenant_id","requested_by","created_at" DESC NULLS LAST);--> statement-breakpoint
CREATE UNIQUE INDEX "audit_exports_active_unique" ON "audit_exports" USING btree ("tenant_id","requested_by") WHERE "audit_exports"."status" in ('queued', 'running');
--> statement-breakpoint
-- ── hand-amended: the controlled vocabularies (IMPLEMENTATION-GUIDE §4) ────
-- Pinned against `AUDIT_EXPORT_STATUSES` / `AUDIT_EXPORT_FAILURE_REASONS`
-- (tenancy/audit-export.command.ts) by test/audit-export.spec.ts. `status`
-- is NOT NULL; `failure_reason` is nullable, so its arm says IS NULL first.
ALTER TABLE "audit_exports" ADD CONSTRAINT "audit_exports_status_check" CHECK ("status" IN (
	'queued', 'running', 'ready', 'failed', 'expired'
));--> statement-breakpoint
ALTER TABLE "audit_exports" ADD CONSTRAINT "audit_exports_failure_reason_check" CHECK (
	"failure_reason" IS NULL OR "failure_reason" IN ('too-many-events', 'interrupted', 'export-error')
);--> statement-breakpoint
ALTER TABLE "audit_exports" ADD CONSTRAINT "audit_exports_attempts_check" CHECK ("attempts" >= 0);--> statement-breakpoint
ALTER TABLE "audit_exports" ADD CONSTRAINT "audit_exports_sha256_check" CHECK (
	"sha256" IS NULL OR "sha256" ~ '^[0-9a-f]{64}$'
);--> statement-breakpoint
-- ── hand-amended: the per-status row shape ────────────────────────────────
--   queued  — nothing started, nothing finished, no result, no reason;
--   running — started and heart-beating, nothing finished, no result;
--   ready   — finished with an expiry and every result field, no reason;
--   failed  — finished with an expiry and a reason (result unconstrained);
--   expired — finished with an expiry; keeps whatever it had (history).
ALTER TABLE "audit_exports" ADD CONSTRAINT "audit_exports_shape_check" CHECK (
	-- Written as one implication per status, so an unknown status passes here
	-- and is refused by its own vocabulary CHECK (the probe pins which).
	("status" <> 'queued' OR (
		"started_at" IS NULL AND "heartbeat_at" IS NULL AND "finished_at" IS NULL AND "expires_at" IS NULL
		AND "row_count" IS NULL AND "byte_size" IS NULL AND "sha256" IS NULL AND "failure_reason" IS NULL))
	AND ("status" <> 'running' OR (
		"started_at" IS NOT NULL AND "heartbeat_at" IS NOT NULL AND "finished_at" IS NULL AND "expires_at" IS NULL
		AND "row_count" IS NULL AND "byte_size" IS NULL AND "sha256" IS NULL AND "failure_reason" IS NULL))
	AND ("status" <> 'ready' OR (
		"finished_at" IS NOT NULL AND "expires_at" IS NOT NULL
		AND "row_count" IS NOT NULL AND "byte_size" IS NOT NULL AND "sha256" IS NOT NULL AND "failure_reason" IS NULL))
	AND ("status" <> 'failed' OR (
		"finished_at" IS NOT NULL AND "expires_at" IS NOT NULL AND "failure_reason" IS NOT NULL))
	AND ("status" <> 'expired' OR (
		"finished_at" IS NOT NULL AND "expires_at" IS NOT NULL))
);--> statement-breakpoint
-- ── hand-amended: the notifications source vocabulary, widened ───────────
-- Drop and re-add (the 0023/0024 precedent). Pinned against
-- `NOTIFICATION_SOURCE_TYPES` by test/notifications.spec.ts.
ALTER TABLE "notifications" DROP CONSTRAINT "notifications_source_type_check";--> statement-breakpoint
ALTER TABLE "notifications" ADD CONSTRAINT "notifications_source_type_check" CHECK ("source_type" IN (
	'stock-adjustment', 'count-variance', 'over-receipt', 'rejected-op',
	'reorder-breach', 'batch-alert', 'qc-hold', 'channel-sync', 'audit-export'
));--> statement-breakpoint
-- ── hand-amended: the recipient pairing, in both directions ──────────────
-- An `audit-export` entry is addressed to its requester and only such an
-- entry carries a recipient. `source_type` is NOT NULL, so both sides of the
-- equality are always true or false — never NULL.
ALTER TABLE "notifications" ADD CONSTRAINT "notifications_recipient_check" CHECK (
	("source_type" = 'audit-export') = ("recipient_user_id" IS NOT NULL)
);--> statement-breakpoint
-- ── hand-amended: RLS — the uniform tenant policy (the 0056 shape) ─────────
ALTER TABLE "audit_exports" ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
ALTER TABLE "audit_export_files" ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
CREATE POLICY "audit_exports_tenant_isolation" ON "audit_exports"
	USING ("tenant_id" = NULLIF(current_setting('app.tenant_id', true), '')::uuid)
	WITH CHECK ("tenant_id" = NULLIF(current_setting('app.tenant_id', true), '')::uuid);--> statement-breakpoint
CREATE POLICY "audit_export_files_tenant_isolation" ON "audit_export_files"
	USING ("tenant_id" = NULLIF(current_setting('app.tenant_id', true), '')::uuid)
	WITH CHECK ("tenant_id" = NULLIF(current_setting('app.tenant_id', true), '')::uuid);--> statement-breakpoint
-- ── the post-migration assertion (the 0064/0067 model) ────────────────────
-- The accepted shapes are inserted first and rolled back by a sentinel, so a
-- CHECK that refuses everything cannot pass. Each refused shape runs in its
-- own subtransaction and must be refused by `check_violation` ON THE NAMED
-- CONSTRAINT — a probe another CHECK happens to refuse proves nothing.
DO $$
DECLARE
	t uuid := gen_random_uuid();
	u uuid := gen_random_uuid();
	h text := repeat('ab', 32);
	refused_by text;
	expected text;
	probe text;
BEGIN
	-- (1) the accepted shapes: every status, a file, the nine source types
	-- (only audit-export with a recipient), and an audit-export tombstone.
	BEGIN
		INSERT INTO "audit_exports" ("id","tenant_id","requested_by","filters","snapshot_at","status","attempts","started_at","heartbeat_at","finished_at","expires_at","row_count","byte_size","sha256","failure_reason")
		VALUES (gen_random_uuid(), t, u, '{}'::jsonb, now(), 'queued', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
		       (gen_random_uuid(), t, gen_random_uuid(), '{}'::jsonb, now(), 'running', 1, now(), now(), NULL, NULL, NULL, NULL, NULL, NULL),
		       (gen_random_uuid(), t, u, '{}'::jsonb, now(), 'ready', 1, now(), now(), now(), now(), 0, 20, h, NULL),
		       (gen_random_uuid(), t, u, '{}'::jsonb, now(), 'failed', 1, now(), now(), now(), now(), NULL, NULL, NULL, 'too-many-events'),
		       (gen_random_uuid(), t, u, '{}'::jsonb, now(), 'failed', 3, now(), now(), now(), now(), NULL, NULL, NULL, 'interrupted'),
		       (gen_random_uuid(), t, u, '{}'::jsonb, now(), 'failed', 0, NULL, NULL, now(), now(), NULL, NULL, NULL, 'export-error'),
		       (gen_random_uuid(), t, u, '{}'::jsonb, now(), 'expired', 1, now(), now(), now(), now(), 4, 30, h, NULL),
		       (gen_random_uuid(), t, u, '{}'::jsonb, now(), 'expired', 1, now(), now(), now(), now(), NULL, NULL, NULL, 'interrupted');
		INSERT INTO "audit_export_files" ("export_id","tenant_id","content") VALUES (gen_random_uuid(), t, '\x1f8b'::bytea);
		INSERT INTO "notifications" ("id","tenant_id","source_type","source_id","warehouse_id","summary","raised_at","surfaced_at","resolved_at","resolution","recipient_user_id")
		VALUES (gen_random_uuid(), t, 'stock-adjustment', gen_random_uuid(), t, '{}'::jsonb, now(), now(), NULL, NULL, NULL),
		       (gen_random_uuid(), t, 'count-variance', gen_random_uuid(), t, '{}'::jsonb, now(), now(), NULL, NULL, NULL),
		       (gen_random_uuid(), t, 'over-receipt', gen_random_uuid(), t, '{}'::jsonb, now(), now(), NULL, NULL, NULL),
		       (gen_random_uuid(), t, 'rejected-op', gen_random_uuid(), NULL, '{}'::jsonb, now(), now(), NULL, NULL, NULL),
		       (gen_random_uuid(), t, 'reorder-breach', gen_random_uuid(), t, '{}'::jsonb, now(), now(), NULL, NULL, NULL),
		       (gen_random_uuid(), t, 'batch-alert', gen_random_uuid(), t, '{}'::jsonb, now(), now(), NULL, NULL, NULL),
		       (gen_random_uuid(), t, 'qc-hold', gen_random_uuid(), t, '{}'::jsonb, now(), now(), NULL, NULL, NULL),
		       (gen_random_uuid(), t, 'channel-sync', gen_random_uuid(), NULL, '{}'::jsonb, now(), now(), NULL, NULL, NULL),
		       (gen_random_uuid(), t, 'audit-export', gen_random_uuid(), NULL, '{}'::jsonb, now(), now(), NULL, NULL, u),
		       (gen_random_uuid(), t, 'audit-export', gen_random_uuid(), NULL, NULL, NULL, NULL, now(), 'expired', u);
		RAISE EXCEPTION USING ERRCODE = 'P0070', MESSAGE = 'rollback the accepted probes';
	EXCEPTION
		WHEN check_violation THEN
			RAISE EXCEPTION 'migration 0070: an accepted shape was refused.';
		WHEN SQLSTATE 'P0070' THEN
			NULL; -- the accepted shapes landed, and the sentinel rolled them back
	END;
	-- (2) the refused shapes, each by its named constraint.
	FOREACH probe IN ARRAY ARRAY[
		'unknown status',
		'unknown failure reason',
		'negative attempts',
		'malformed sha256',
		'queued with started_at',
		'queued with a failure reason',
		'running without heartbeat_at',
		'running with finished_at',
		'ready without sha256',
		'ready without expires_at',
		'ready with a failure reason',
		'failed without a failure reason',
		'failed without finished_at',
		'expired without expires_at',
		'unknown source type',
		'audit-export without a recipient',
		'a capability source with a recipient'
	] LOOP
		refused_by := NULL;
		expected := CASE probe
			WHEN 'unknown status' THEN 'audit_exports_status_check'
			WHEN 'unknown failure reason' THEN 'audit_exports_failure_reason_check'
			WHEN 'negative attempts' THEN 'audit_exports_attempts_check'
			WHEN 'malformed sha256' THEN 'audit_exports_sha256_check'
			WHEN 'unknown source type' THEN 'notifications_source_type_check'
			WHEN 'audit-export without a recipient' THEN 'notifications_recipient_check'
			WHEN 'a capability source with a recipient' THEN 'notifications_recipient_check'
			ELSE 'audit_exports_shape_check'
		END;
		BEGIN
			CASE probe
				WHEN 'unknown status' THEN
					INSERT INTO "audit_exports" ("id","tenant_id","requested_by","filters","snapshot_at","status")
					VALUES (gen_random_uuid(), t, u, '{}'::jsonb, now(), 'done');
				WHEN 'unknown failure reason' THEN
					INSERT INTO "audit_exports" ("id","tenant_id","requested_by","filters","snapshot_at","status","finished_at","expires_at","failure_reason")
					VALUES (gen_random_uuid(), t, u, '{}'::jsonb, now(), 'failed', now(), now(), 'boom');
				WHEN 'negative attempts' THEN
					INSERT INTO "audit_exports" ("id","tenant_id","requested_by","filters","snapshot_at","status","attempts")
					VALUES (gen_random_uuid(), t, u, '{}'::jsonb, now(), 'queued', -1);
				WHEN 'malformed sha256' THEN
					INSERT INTO "audit_exports" ("id","tenant_id","requested_by","filters","snapshot_at","status","finished_at","expires_at","row_count","byte_size","sha256")
					VALUES (gen_random_uuid(), t, u, '{}'::jsonb, now(), 'ready', now(), now(), 1, 1, 'NOT-A-DIGEST');
				WHEN 'queued with started_at' THEN
					INSERT INTO "audit_exports" ("id","tenant_id","requested_by","filters","snapshot_at","status","started_at")
					VALUES (gen_random_uuid(), t, u, '{}'::jsonb, now(), 'queued', now());
				WHEN 'queued with a failure reason' THEN
					INSERT INTO "audit_exports" ("id","tenant_id","requested_by","filters","snapshot_at","status","failure_reason")
					VALUES (gen_random_uuid(), t, u, '{}'::jsonb, now(), 'queued', 'interrupted');
				WHEN 'running without heartbeat_at' THEN
					INSERT INTO "audit_exports" ("id","tenant_id","requested_by","filters","snapshot_at","status","started_at")
					VALUES (gen_random_uuid(), t, u, '{}'::jsonb, now(), 'running', now());
				WHEN 'running with finished_at' THEN
					INSERT INTO "audit_exports" ("id","tenant_id","requested_by","filters","snapshot_at","status","started_at","heartbeat_at","finished_at")
					VALUES (gen_random_uuid(), t, u, '{}'::jsonb, now(), 'running', now(), now(), now());
				WHEN 'ready without sha256' THEN
					INSERT INTO "audit_exports" ("id","tenant_id","requested_by","filters","snapshot_at","status","finished_at","expires_at","row_count","byte_size")
					VALUES (gen_random_uuid(), t, u, '{}'::jsonb, now(), 'ready', now(), now(), 1, 1);
				WHEN 'ready without expires_at' THEN
					INSERT INTO "audit_exports" ("id","tenant_id","requested_by","filters","snapshot_at","status","finished_at","row_count","byte_size","sha256")
					VALUES (gen_random_uuid(), t, u, '{}'::jsonb, now(), 'ready', now(), 1, 1, h);
				WHEN 'ready with a failure reason' THEN
					INSERT INTO "audit_exports" ("id","tenant_id","requested_by","filters","snapshot_at","status","finished_at","expires_at","row_count","byte_size","sha256","failure_reason")
					VALUES (gen_random_uuid(), t, u, '{}'::jsonb, now(), 'ready', now(), now(), 1, 1, h, 'export-error');
				WHEN 'failed without a failure reason' THEN
					INSERT INTO "audit_exports" ("id","tenant_id","requested_by","filters","snapshot_at","status","finished_at","expires_at")
					VALUES (gen_random_uuid(), t, u, '{}'::jsonb, now(), 'failed', now(), now());
				WHEN 'failed without finished_at' THEN
					INSERT INTO "audit_exports" ("id","tenant_id","requested_by","filters","snapshot_at","status","expires_at","failure_reason")
					VALUES (gen_random_uuid(), t, u, '{}'::jsonb, now(), 'failed', now(), 'export-error');
				WHEN 'expired without expires_at' THEN
					INSERT INTO "audit_exports" ("id","tenant_id","requested_by","filters","snapshot_at","status","finished_at")
					VALUES (gen_random_uuid(), t, u, '{}'::jsonb, now(), 'expired', now());
				WHEN 'unknown source type' THEN
					INSERT INTO "notifications" ("id","tenant_id","source_type","source_id","summary","raised_at","surfaced_at")
					VALUES (gen_random_uuid(), t, 'task-assignment', gen_random_uuid(), '{}'::jsonb, now(), now());
				WHEN 'audit-export without a recipient' THEN
					INSERT INTO "notifications" ("id","tenant_id","source_type","source_id","summary","raised_at","surfaced_at")
					VALUES (gen_random_uuid(), t, 'audit-export', gen_random_uuid(), '{}'::jsonb, now(), now());
				WHEN 'a capability source with a recipient' THEN
					INSERT INTO "notifications" ("id","tenant_id","source_type","source_id","summary","raised_at","surfaced_at","recipient_user_id")
					VALUES (gen_random_uuid(), t, 'qc-hold', gen_random_uuid(), '{}'::jsonb, now(), now(), u);
			END CASE;
		EXCEPTION WHEN check_violation THEN
			GET STACKED DIAGNOSTICS refused_by = CONSTRAINT_NAME;
		END;
		IF refused_by IS NULL THEN
			RAISE EXCEPTION 'migration 0070: the CHECK probe "%" was not refused.', probe;
		END IF;
		IF refused_by <> expected THEN
			RAISE EXCEPTION 'migration 0070: the CHECK probe "%" was refused by % — expected %.', probe, refused_by, expected;
		END IF;
	END LOOP;
	IF EXISTS (SELECT 1 FROM "audit_exports" WHERE "tenant_id" = t)
		OR EXISTS (SELECT 1 FROM "audit_export_files" WHERE "tenant_id" = t)
		OR EXISTS (SELECT 1 FROM "notifications" WHERE "tenant_id" = t) THEN
		RAISE EXCEPTION 'migration 0070: a CHECK probe row survived.';
	END IF;
END $$;
